param([string]$ProjectRoot = (Join-Path $env:USERPROFILE 'Projects\ChallengeEngineV01_STATELESS'))
$ErrorActionPreference = 'Stop'
$RunnerPath = $MyInvocation.MyCommand.Path
function Get-Sha256([string]$Path) { if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "Missing file: $Path" }; return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() }
function Assert-AsciiSource([string]$Path) { foreach ($byte in [System.IO.File]::ReadAllBytes($Path)) { if ($byte -gt 127) { throw "Runner source is not ASCII-safe: $Path" } } }
function Invoke-Python([string]$Python,[string[]]$Arguments,[string]$WorkingDirectory,[string]$Stdout,[string]$Stderr) {
    $quoted=@(); foreach($argument in $Arguments){$value=[string]$argument;if($value.Contains(' ') -or $value.Contains([char]9)){$quoted+=('"'+$value+'"')}else{$quoted+=$value}}
    $p=Start-Process -FilePath $Python -ArgumentList ($quoted -join ' ') -WorkingDirectory $WorkingDirectory -Wait -PassThru -NoNewWindow -RedirectStandardOutput $Stdout -RedirectStandardError $Stderr
    if($null -eq $p){throw 'Start-Process returned no process'}; return $p.ExitCode
}
