$frozenSha=Get-Sha256 $frozen;if($frozenSha -ne 'e405d08e4d166b1ad95953558f4a088e73eea9527e6e89244beb4096eac4b953'){throw 'Frozen C11-C manifest mismatch'};Write-Host 'FROZEN_C11C_MANIFEST=PASS'
$basePins=Get-Content -LiteralPath $pinsPath -Raw -Encoding UTF8|ConvertFrom-Json;if($basePins.source_pins.Count -ne 40){throw 'Expected 40 base source pins'}
