foreach($pin in $local.local_pins){$rel=([string]$pin.path).Replace('/','\');if([IO.Path]::IsPathRooted($rel) -or $rel.Contains('..')){throw "Unsafe local pin: $rel"};if((Get-Sha256 (Join-Path $ProjectRoot $rel)) -ne ([string]$pin.sha256).ToLowerInvariant()){throw "Local tool/source pin mismatch: $rel"}}
