$receipt=[ordered]@{schema='C11E-E4B-LOOP-FAMILY-CONTRACT-RUNNER-RECEIPT-V2';status='PASS_OPERATOR_DECISIONS_AND_FAMILY_STATIC_CONTRACT_AUDIT_ONLY';run_id=$run;project_root=$ProjectRoot;powershell_version=$PSVersionTable.PSVersion.ToString();python_version=$pv;frozen_c11c_manifest_sha256=$frozenSha;base_source_pin_count=40;local_tool_pins=8;focused_test_methods=8;tested_canonical_selectors=27;mp4_present_in_active_checkout=$cov.mp4_present_in_project_root_count;visual_review_performed=$false;report_path=$reportPath;report_sha256=$reportSha;stdout_sha256=[ordered]@{tests=(Get-Sha256 $to);audit=(Get-Sha256 $ao)};stderr_sha256=[ordered]@{tests=(Get-Sha256 $te);audit=(Get-Sha256 $ae)};test_exit_code=$tx;audit_exit_code=$ax;renderer_native_input_emitted=$false;launcher_invoked=$false;godot_invoked=$false;ffmpeg_invoked=$false;audio_generated=$false;media_created=$false;c11c_source_mutation=$false;d4_8='BLOCKED';d9_10='PREPARE_ONLY';release_authority='NONE'}
